<script setup lang="ts">
import {computed,onUnmounted,ref} from 'vue'
interface Product{id:number;name:string;priceCents:number;stock:number}
interface Order{id:number;productId:number;quantity:number;totalCents:number;status:string;createdAt:string}
interface Overview{status:string;sampledAt:string;ordersWaiting:number|null;outboxPending:number|null}
const token=ref(''),labToken=ref(''),tab=ref('catalog'),error=ref(''),success=ref(''),busy=ref(false),connected=ref(false),loadedAt=ref('')
const products=ref<Product[]>([]),orders=ref<Order[]>([]),overview=ref<Overview>(),quantities=ref<Record<number,number>>({}),region=ref('LOCAL')
const instance=ref('a'),seconds=ref(20),mode=ref('HTTP_5XX'),resource=ref('DB_LOCK'),labState=ref<unknown>(),httpState=ref<unknown>()
const drafts=new Map<string,string>()
const totalStock=computed(()=>loadedAt.value?products.value.reduce((n,p)=>n+p.stock,0):null)
const labels:Record<string,string>={ACCEPTED:'待备货',READY:'已备货',CANCELLED:'已取消'}
const icons=['⌨','↗','▣']
const money=(cents:number)=>new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY'}).format(cents/100)
const time=(s:string)=>new Date(/[Z+]/.test(s.slice(10))?s:s+'Z').toLocaleString('zh-CN',{hour12:false})
const message=(e:unknown)=>e instanceof Error?e.message:String(e)
async function api<T>(path:string,options:RequestInit={},lab=false):Promise<T>{
  const response=await fetch(path,{...options,headers:{Authorization:'Bearer '+token.value,'Content-Type':'application/json',...(lab?{'X-Lab-Token':labToken.value}:{}),...options.headers},signal:AbortSignal.timeout(15000)})
  const body=await response.json()
  if(!response.ok)throw new Error(`${body.message||'请求失败'}（HTTP ${response.status} · ${body.code||''}）`)
  return body
}
async function reload(){
  if(!token.value)return
  try{const [p,o,v]=await Promise.all([api<Product[]>('/api/products'),api<Order[]>('/api/orders'),api<Overview>('/api/overview')]);products.value=p;orders.value=o;overview.value=v;loadedAt.value=new Date().toLocaleTimeString('zh-CN');connected.value=true;error.value=''}
  catch(e){error.value=message(e);connected.value=false}
}
async function connect(){busy.value=true;try{await reload()}finally{busy.value=false}}
async function create(product:Product){
  const quantity=quantities.value[product.id]||1,key=`${product.id}:${quantity}:${region.value}`
  // 超时后保留同一请求的键；手动重试不会因响应丢失而再次扣库存。
  if(!drafts.has(key))drafts.set(key,crypto.randomUUID())
  busy.value=true;error.value='';success.value=''
  try{const order=await api<Order>('/api/orders',{method:'POST',headers:{'Idempotency-Key':drafts.get(key)!},body:JSON.stringify({productId:product.id,quantity,region:region.value})});drafts.delete(key);success.value=`订单 #${order.id} 已受理，等待真实 Kafka 消费备货。`;await reload()}
  catch(e){error.value=message(e)+'。同样参数再次提交将复用幂等键。'}finally{busy.value=false}
}
async function cancel(order:Order){busy.value=true;try{await api(`/api/orders/${order.id}/cancel`,{method:'POST'});await reload();success.value=`订单 #${order.id} 已取消并归还库存。`}catch(e){error.value=message(e)}finally{busy.value=false}}
async function restock(product:Product){busy.value=true;try{await api(`/api/products/${product.id}/restock`,{method:'POST',body:JSON.stringify({quantity:100})});await reload();success.value=product.name+' 已补货 100 件。'}catch(e){error.value=message(e)}finally{busy.value=false}}
async function readLab(){error.value='';try{httpState.value=await api(`/ops/${instance.value}/faults`,{},true);labState.value=instance.value==='delivery'?undefined:await api(`/ops/${instance.value}/lab`,{},true)}catch(e){error.value=message(e)}}
async function startHttp(){busy.value=true;error.value='';try{httpState.value=await api(`/ops/${instance.value}/faults`,{method:'POST',body:JSON.stringify({mode:mode.value,seconds:seconds.value})},true);success.value='HTTP 场景已设置；故障影响以实际请求和监控为准。'}catch(e){error.value=message(e)}finally{busy.value=false}}
async function startResource(){busy.value=true;error.value='';try{labState.value=await api(`/ops/${instance.value}/lab`,{method:'POST',body:JSON.stringify({scenario:resource.value,seconds:seconds.value})},true);success.value='资源演练已受理；实际任务数和到期时间见下方。'}catch(e){error.value=message(e)}finally{busy.value=false}}
async function clear(){busy.value=true;try{httpState.value=await api(`/ops/${instance.value}/faults`,{method:'DELETE'},true);if(instance.value!=='delivery')labState.value=await api(`/ops/${instance.value}/lab`,{method:'DELETE'},true);success.value='取消已请求，资源释放状态以活动任务数为准。'}catch(e){error.value=message(e)}finally{busy.value=false}}
let polling=false
const timer=setInterval(async()=>{if(token.value&&!busy.value&&!polling&&!document.hidden){polling=true;try{await reload()}finally{polling=false}}},5000)
onUnmounted(()=>clearInterval(timer))
</script>
<template>
  <div class="shop-shell">
    <aside><a class="brand" href="/">F<span>FIELD SHOP<small>业务与可观测性实训</small></span></a><div class="side-label">WORKSPACE / STAGING</div><nav><button aria-label="商品与库存" title="商品与库存" :class="{active:tab==='catalog'}" @click="tab='catalog'">▦ <span>商品与库存</span></button><button aria-label="订单记录" title="订单记录" :class="{active:tab==='orders'}" @click="tab='orders'">▤ <span>订单记录</span></button><button aria-label="故障演练" title="故障演练" :class="{active:tab==='lab'}" @click="tab='lab'">⌁ <span>故障演练</span></button></nav><div class="side-foot"><i/>独立部署项目<small>真实 MySQL · Redis · Kafka</small></div></aside>
    <main>
      <div class="topline"><span>巡航商店 <b>/</b> {{tab==='catalog'?'商品与库存':tab==='orders'?'订单记录':'测试环境演练'}}</span><span :class="connected?'online':'offline'">● {{connected?'业务接口可用':'尚未连接 / 请求异常'}}</span></div>
      <header class="heading"><div><p class="eyebrow">A SMALL SHOP. REAL OPERATIONS.</p><h1>{{tab==='catalog'?'每一单，都有真实的流转。':tab==='orders'?'从下单，到完成备货。':'让故障留下可核查的证据。'}}</h1><p>双实例业务服务、独立运费依赖，以及可以追踪的库存与异步消息。</p></div><span class="environment">STAGING</span></header>
      <section class="access"><label>业务访问口令<input v-model="token" type="password" autocomplete="off" placeholder="填写本项目 SHOP_API_TOKEN，仅保存在页面内存" /></label><button class="primary" :disabled="busy||!token" @click="connect">连接并刷新</button><small>上次成功读取 {{loadedAt||'—'}} · 每 5 秒刷新</small></section>
      <div v-if="error" class="notice error" role="alert">{{error}} <small v-if="loadedAt">下方保留上次成功读取的数据。</small></div><div v-if="success" class="notice success" role="status">{{success}}</div>
      <div class="stats"><article><span>真实可售库存</span><strong>{{totalStock??'—'}}<small>件</small></strong><p>MySQL 条件扣减，防止超卖</p></article><article><span>待备货订单</span><strong>{{overview?.ordersWaiting??'—'}}<small>单</small></strong><p>实际数据库状态，不等于 Kafka offset lag</p></article><article><span>待发送消息</span><strong>{{overview?.outboxPending??'—'}}<small>条</small></strong><p>持久化 Outbox，失败后可继续发送</p></article><article><span>业务采样状态</span><strong class="sample-state">{{overview?.status==='SUCCESS'?'可用':overview?'不可用':'待连接'}}</strong><p>{{overview?time(overview.sampledAt):'不以默认零值代替采样'}}</p></article></div>
      <template v-if="tab==='catalog'">
        <div class="section-title"><div><h2>精选商品</h2><p>真实库存与价格，订单金额包含独立服务计算的运费。</p></div><label class="region">配送区域<select v-model="region"><option value="LOCAL">本地 · 基础运费 ¥5</option><option value="REMOTE">偏远 · 基础运费 ¥15</option></select></label></div>
        <div v-if="products.length" class="products"><article v-for="(product,i) in products" :key="product.id"><div class="product-art" :class="'art-'+i"><span>{{icons[i%icons.length]}}</span><small>FIELD / {{String(product.id).padStart(2,'0')}}</small></div><div class="product-info"><span class="stock">{{product.stock>0?'有货':'暂时缺货'}} · {{product.stock}} 件</span><h3>{{product.name}}</h3><p>SKU {{product.id}} / 可追踪库存流水</p><div class="purchase"><strong>{{money(product.priceCents)}}</strong><label>数量<input v-model.number="quantities[product.id]" type="number" min="1" max="20" :placeholder="'1'" :aria-label="product.name+'数量'" /></label></div><button class="primary full" :disabled="busy||!token||!product.stock" @click="create(product)">下单并预留库存</button><button class="text" :disabled="busy||!token" @click="restock(product)">补货 +100 件</button></div></article></div>
        <div v-else class="empty">{{error?'目录读取失败，请检查真实依赖状态。':'填写口令后读取真实商品，不预填展示数据。'}}</div>
        <section class="flow"><span>01 <b>提交订单</b><small>幂等键</small></span><i>→</i><span>02 <b>库存预留</b><small>本地事务</small></span><i>→</i><span>03 <b>发布消息</b><small>Kafka / Outbox</small></span><i>→</i><span>04 <b>完成备货</b><small>消费去重</small></span></section>
      </template>
      <section v-else-if="tab==='orders'" class="order-panel"><div class="section-title"><div><h2>最近订单</h2><p>最多 100 条。已备货不表示真实付款或快递已发货。</p></div><button class="secondary" :disabled="busy||!token" @click="connect">刷新记录</button></div><div class="table-scroll"><table><thead><tr><th>订单</th><th>商品 / 数量</th><th>含运费金额</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>#{{o.id}}</td><td>SKU {{o.productId}} / {{o.quantity}} 件</td><td>{{money(o.totalCents)}}</td><td><span class="badge" :class="o.status">{{labels[o.status]||o.status}}</span></td><td>{{time(o.createdAt)}}</td><td><button v-if="o.status==='ACCEPTED'" class="text" :disabled="busy" @click="cancel(o)">取消并释放库存</button><span v-else>—</span></td></tr><tr v-if="!orders.length"><td colspan="6" class="empty">{{loadedAt?'尚无订单。可以先购买一件商品。':'连接后显示真实订单记录。'}}</td></tr></tbody></table></div></section>
      <section v-else class="lab-panel"><div class="section-title"><div><h2>测试环境故障控制台</h2><p>只在显式 demo 环境可用；生产部署返回 404。资源场景有更短上限，到期自动释放。</p></div></div><div class="lab-fields"><label>独立演练口令<input v-model="labToken" type="password" autocomplete="off" placeholder="SHOP_LAB_TOKEN，不保存到浏览器存储" /></label><label>目标实例<select v-model="instance" @change="labState=undefined;httpState=undefined"><option value="a">业务实例 A</option><option value="b">业务实例 B</option><option value="delivery">运费服务</option></select></label><label>请求持续时间（秒）<input v-model.number="seconds" type="number" min="1" max="60" /></label></div><div class="lab-actions"><label>HTTP 场景<select v-model="mode"><option value="HTTP_5XX">业务接口返回真实 503</option><option value="SLOW">业务请求增加 1.5 秒延迟</option><option value="NONE">恢复正常</option></select></label><button class="secondary" :disabled="busy||!token||!labToken" @click="startHttp">设置 HTTP 场景</button></div><div class="lab-actions"><label>资源 / 消息场景<select v-model="resource" :disabled="instance==='delivery'"><option value="DB_LOCK">锁住 SKU 1 · 最长 20 秒</option><option value="DB_POOL">占用 6 个连接 · 最长 20 秒</option><option value="CPU">单线程 CPU · 最长 5 秒</option><option value="HEAP">持有 32 MiB 内存 · 最长 30 秒</option><option value="CONSUMER_PAUSE">暂停本实例消费 · 最长 60 秒</option></select></label><button class="secondary" :disabled="busy||!token||!labToken||instance==='delivery'" @click="startResource">开始资源演练</button></div><div class="lab-buttons"><button class="secondary" :disabled="busy||!token||!labToken" @click="readLab">读取实际状态</button><button class="danger" :disabled="busy||!token||!labToken" @click="clear">取消当前实例的演练</button></div><pre v-if="httpState||labState">{{JSON.stringify({http:httpState,resources:labState},null,2)}}</pre><div class="lab-note">Redis、Kafka、数据库和实例停机使用项目自带场景脚本执行真实启停；本页面不提供服务器命令执行。要暂停所有消费，需要分别暂停实例 A、B。请在隔离测试服务器演练。</div></section>
      <footer>FIELD SHOP / Java 21 · MySQL · Redis · Kafka <span>真实业务样本 · 不包含外部支付、真实收货地址或快递下单</span></footer>
    </main>
  </div>
</template>
<style>
