nt-size:9px;font-weight:650;letter-spacing:2px;color:#8e9caa;margin:0 0 13px}h1{font-size:28px;letter-spacing:-.5px;font-weight:650;margin:0 0 13px}.heading>div>p:last-child{color:#8a97a4;font-size:12px;line-height:1.8;margin:0}.environment{font-size:10px;letter-spacing:1px;color:#6d8e85;background:#e6ede9;padding:8px 11px;border-radius:4px}.access{display:flex;align-items:flex-end;gap:13px;margin-bottom:20px}.access label{width:440px;max-width:100%}.access small{margin-left:auto;font-size:10px;color:#97a3b1;padding-bottom:12px}.primary,.secondary,.danger{padding:11px 17px;border:1px solid transparent;font-size:12px;white-space:nowrap}.primary{background:#244c59;color:white}.secondary{background:white;border-color:#dce3e8;color:#5a7083}.danger{background:#fbefeb;border-color:#eeddd7;color:#ad7061}.full{width:100%}.text{border:0;background:transparent;color:#8a9caa;padding:10px 0;font-size:11px}.notice{padding:13px 16px;border:1px solid;border-radius:6px;font-size:12px;line-height:1.9;margin:14px 0;overflow-wrap:anywhere}.notice.error{background:#fff3ee;color:#b17b68;border-color:#f0ded6}.notice.success{background:#edf5f0;color:#638773;border-color:#d6e8dc}.notice small{display:block}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:24px 0 34px}.stats article{background:white;border:1px solid #e4e8ec;padding:19px 21px;border-radius:8px}.stats article>span{font-size:11px;color:#8393a1}.stats strong{display:block;font-size:26px;font-weight:600;margin:15px 0 12px;color:#2e4b57}.stats strong small{font-size:10px;font-weight:400;color:#9aa7b1;margin-left:6px}.stats strong.sample-state{font-size:22px;padding-top:3px}.stats p{font-size:10px;color:#9aa6b1;line-height:1.7;margin:0}.section-title{display:flex;justify-content:space-between;gap:15px;align-items:center;margin:20px 0}h2{font-size:17px;margin:0 0 9px;font-weight:600}.section-title p{font-size:11px;color:#96a1ab;margin:0;line-height:1.8}.region{font-size:10px}.region select{font-size: